#[test]
fn a_zip_of_unequal_sides_is_sigmastates_pair_of_cols() {
    let wrong = wrong_rows(UNEQUAL_PAIRS);
    assert!(
        wrong.is_empty(),
        "{} of {} rows:\n{}",
        wrong.len(),
        UNEQUAL_PAIRS.len(),
        wrong.join("\n")
    );
}

