#[test]
fn the_readers_of_unequal_pairs_walk_as_sigmastates_do() {
    let wrong = wrong_rows(UNEQUAL_PAIRS_READERS);
    assert!(
        wrong.is_empty(),
        "{} of {} rows:\n{}",
        wrong.len(),
        UNEQUAL_PAIRS_READERS.len(),
        wrong.join("\n")
    );
}

