#[test]
fn an_append_from_the_activation_is_sigmastates() {
    let wrong = wrong_rows(OBJECT_ARRAYS);
    assert!(
        wrong.is_empty(),
        "{} of {} rows:\n{}",
        wrong.len(),
        OBJECT_ARRAYS.len(),
        wrong.join("\n")
    );
}

