#[test]
fn an_append_result_is_read_by_its_class() {
    let wrong = wrong_rows(OBJECT_ARRAYS_BY_CLASS);
    assert!(
        wrong.is_empty(),
        "{} of {} rows:\n{}",
        wrong.len(),
        OBJECT_ARRAYS_BY_CLASS.len(),
        wrong.join("\n")
    );
}
